/**
 * Pure "Lights Out" logic. Toggling a cell flips it and its orthogonal neighbours.
 * Puzzles are generated by applying random toggles to the solved board, so they are
 * always solvable. No React Native dependencies.
 */

export type Grid = boolean[][];

export function createEmpty(size: number): Grid {
  return Array.from({ length: size }, () => Array.from({ length: size }, () => false));
}

export function cloneGrid(grid: Grid): Grid {
  return grid.map((row) => [...row]);
}

/** Flips (r,c) and its orthogonal neighbours. Returns a new grid. */
export function toggleCell(grid: Grid, r: number, c: number): Grid {
  const size = grid.length;
  const next = cloneGrid(grid);
  const flip = (rr: number, cc: number) => {
    if (rr >= 0 && rr < size && cc >= 0 && cc < size) next[rr][cc] = !next[rr][cc];
  };
  flip(r, c);
  flip(r - 1, c);
  flip(r + 1, c);
  flip(r, c - 1);
  flip(r, c + 1);
  return next;
}

/** Generates a solvable puzzle by applying `shuffles` random toggles from solved. */
export function createPuzzle(size: number, shuffles: number): Grid {
  let grid = createEmpty(size);
  for (let i = 0; i < shuffles; i++) {
    grid = toggleCell(grid, Math.floor(Math.random() * size), Math.floor(Math.random() * size));
  }
  // Guarantee it is not already solved.
  if (isSolved(grid)) return toggleCell(grid, 0, 0);
  return grid;
}

export function isSolved(grid: Grid): boolean {
  return grid.every((row) => row.every((on) => !on));
}

export function countOn(grid: Grid): number {
  return grid.reduce((sum, row) => sum + row.filter(Boolean).length, 0);
}
